#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-25 21:50 — TASK 4 LAST, after the synthetic family loop and the scale runs
# ("SCALE RUNS DONE"): split -> 17 Isaac families on the -fishdeterministic images -> off -> pipelines -> "TASK4 DONE".
set -u; cd "$(dirname "$0")/.."
LD=$HOME/fish_traces/night_20261025_final; mkdir -p "$LD"
log() { echo "[$(date +%T)] $*" | tee -a "$LD/queue.log"; }
EV=ros2:fish_msg_retain,ros2:fish_msg_release,ros2:fish_msg_type,ros2:fish_msg_stamp,ros2:fish_msg_ids
while ! grep -q "PRE-TASK4 DONE" "$LD/queue.log" 2>/dev/null; do sleep 120; done   # 23:45: after queue5 (1c pipelines + family re-runs)
# 02:30 (26th): queue5 skipped the scale re-analyses (log-name bug); scripts/night_scale2_reanalyze_20261026.sh runs them and writes
# "SCALE2 DONE" to synth_scale2.log. Wait for it, with a 04:30 deadline so TASK 4 is never blocked by a dead driver.
DL=$(date -d "04:30" +%s); while ! grep -q "SCALE2 DONE" "$LD/synth_scale2.log" 2>/dev/null && [ "$(date +%s)" -lt "$DL" ]; do sleep 60; done
grep -q "SCALE2 DONE" "$LD/synth_scale2.log" 2>/dev/null || log "task4: scale2 deadline 04:30 passed without SCALE2 DONE; starting anyway"
[ -f "$LD/STOP" ] && { log "task4: STOP file present; not starting"; exit 0; }
sudo -n /usr/local/sbin/fish-host-perf-mode split >> "$LD/queue.log" 2>&1 || { log "task4 ABORT: split failed"; exit 1; }
log "task4: 17 Isaac families (split)"; M=$(ls -d "$HOME"/fish_traces/fish_2* | sort | tail -1)
for F in apriltag bi3d bi3d_freespace detectnet dnn_image_encoder dope ess image_proc nitros_bridge nvblox rtdetr segformer stereo_image_proc tensor_rt triton unet visual_slam; do
  log "task4 $F"
  IMG_OVERRIDE=fish-r2b-$F-fishdeterministic:latest REPS=1 MODES=lttng DEST_BASE="$LD/task4c" SMOKE_TIMEOUT=1200 FISH_EXTRA_EVENTS=$EV \
    bash scripts/overhead_sweep_v8.sh "$F" > "$LD/task4c_$F.log" 2>&1 || log "task4 $F rc=$?"
  log "  $F: $(grep "^$F,lttng" "$LD/task4c/runs.csv" 2>/dev/null | tail -1)"
done
sudo -n /usr/local/sbin/fish-host-perf-mode off >> "$LD/queue.log" 2>&1; log "host off; task4 pipelines"
for d in $(ls -d "$HOME"/fish_traces/fish_2* | sort | awk -v b="$M" '$0 > b'); do
  S=$(basename "$d"); grep -q "^$S$" "$LD/pipelines_done.txt" 2>/dev/null && continue
  log "pipeline $S"; bash scripts/post_run_pipeline.sh "$S" "$HOME/fish_traces/analysis_$S" > "$LD/pipeline_$S.log" 2>&1 || log "pipeline $S FAILED"
  echo "$S" >> "$LD/pipelines_done.txt"; echo "$S" >> "$LD/task4_sessions.txt"
done
